# Weitere App-Anleitungen (Typ H): Einrichtung, Stärken und Grenzen. Nominative Nennung, keine Angaben zu Preisen Dritter.
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from kit import page, table, steps, tip

A = "iptv-apps"
STORE = "<p>Funktionsumfang, Preise und Verfügbarkeit der App legt der jeweilige Entwickler fest und können sich ändern. Prüfen Sie den aktuellen Stand im Store.</p>"
ZUG = '<p>Zugangsdaten erhalten Sie nach der Bestellung oder im <a href="/kostenloser-test/">kostenlosen Test</a>.</p>'


def app(slug, nav, name, os_, title, desc, h1, eyebrow, lead, answer, table_rows, how, strengths, faq, related, kw, card):
    return page(slug, A, nav, title, desc, h1, eyebrow, lead, answer,
                [("ueberblick", f"{name} im Überblick", table(["Merkmal", "Angabe"], table_rows) + STORE),
                 ("einrichtung", f"{name} einrichten", steps(how) + ZUG),
                 ("staerken", f"Stärken und Grenzen von {name}", strengths),
                 ],
                faq, related, kw, card, app={"name": name, "os": os_})


